//! HTTP routes and handlers.

use std::collections::BTreeMap;
use std::sync::Arc;

use axum::Router;
use axum::body::Bytes;
use axum::extract::{DefaultBodyLimit, Path, RawQuery, State};
use axum::http::StatusCode;
use axum::response::{IntoResponse, Json, Response};
use axum::routing::{MethodRouter, get};
use serde::Serialize;
use serde_json::json;

use crate::model::{ListQuery, Note, NoteInput, parse_id};
use crate::store::Store;

const MAX_BODY_BYTES: usize = 16 * 1024 * 1024;

type AppState = Arc<Store>;

pub fn router(store: Arc<Store>) -> Router {
    Router::new()
        .route("/health", with_405(get(health)))
        .route("/notes", with_405(get(list_notes).post(create_note)))
        .route(
            "/notes/{id}",
            with_405(get(get_note).put(replace_note).delete(delete_note)),
        )
        .route("/stats", with_405(get(stats)))
        .route("/tags", with_405(get(tags)))
        .fallback(|| async { ApiError::NotFound })
        .layer(DefaultBodyLimit::max(MAX_BODY_BYTES))
        .with_state(store)
}

fn with_405(route: MethodRouter<AppState>) -> MethodRouter<AppState> {
    route.fallback(|| async { ApiError::MethodNotAllowed })
}

#[derive(Debug)]
pub enum ApiError {
    BadRequest(String),
    NotFound,
    MethodNotAllowed,
    Internal(String),
}

impl From<rusqlite::Error> for ApiError {
    fn from(e: rusqlite::Error) -> Self {
        Self::Internal(e.to_string())
    }
}

impl From<tokio::task::JoinError> for ApiError {
    fn from(e: tokio::task::JoinError) -> Self {
        Self::Internal(e.to_string())
    }
}

impl IntoResponse for ApiError {
    fn into_response(self) -> Response {
        let (status, message) = match self {
            Self::BadRequest(msg) => (StatusCode::BAD_REQUEST, msg),
            Self::NotFound => (StatusCode::NOT_FOUND, "not found".into()),
            Self::MethodNotAllowed => {
                (StatusCode::METHOD_NOT_ALLOWED, "method not allowed".into())
            }
            Self::Internal(msg) => {
                eprintln!("internal error: {msg}");
                (StatusCode::INTERNAL_SERVER_ERROR, "internal error".into())
            }
        };
        (status, Json(json!({ "error": message }))).into_response()
    }
}

type ApiResult<T> = Result<T, ApiError>;

/// Runs a blocking database operation off the async executor.
async fn with_store<T, F>(store: AppState, op: F) -> ApiResult<T>
where
    T: Send + 'static,
    F: FnOnce(&Store) -> rusqlite::Result<T> + Send + 'static,
{
    Ok(tokio::task::spawn_blocking(move || op(&store)).await??)
}

fn note_id(segment: &str) -> ApiResult<i64> {
    parse_id(segment).ok_or(ApiError::NotFound)
}

fn note_input(body: &[u8]) -> ApiResult<NoteInput> {
    NoteInput::from_json(body).map_err(ApiError::BadRequest)
}

async fn health() -> &'static str {
    "ok"
}

async fn create_note(
    State(store): State<AppState>,
    body: Bytes,
) -> ApiResult<(StatusCode, Json<Note>)> {
    let input = note_input(&body)?;
    let note = with_store(store, move |s| s.create(&input)).await?;
    Ok((StatusCode::CREATED, Json(note)))
}

async fn get_note(State(store): State<AppState>, Path(id): Path<String>) -> ApiResult<Json<Note>> {
    let id = note_id(&id)?;
    with_store(store, move |s| s.get(id))
        .await?
        .map(Json)
        .ok_or(ApiError::NotFound)
}

async fn replace_note(
    State(store): State<AppState>,
    Path(id): Path<String>,
    body: Bytes,
) -> ApiResult<Json<Note>> {
    let id = note_id(&id)?;
    let input = note_input(&body)?;
    with_store(store, move |s| s.replace(id, &input))
        .await?
        .map(Json)
        .ok_or(ApiError::NotFound)
}

async fn delete_note(
    State(store): State<AppState>,
    Path(id): Path<String>,
) -> ApiResult<StatusCode> {
    let id = note_id(&id)?;
    if with_store(store, move |s| s.delete(id)).await? {
        Ok(StatusCode::NO_CONTENT)
    } else {
        Err(ApiError::NotFound)
    }
}

#[derive(Serialize)]
struct NoteList {
    notes: Vec<Note>,
}

async fn list_notes(
    State(store): State<AppState>,
    RawQuery(raw): RawQuery,
) -> ApiResult<Json<NoteList>> {
    let query = ListQuery::parse(raw.as_deref()).map_err(ApiError::BadRequest)?;
    let notes = with_store(store, move |s| s.list(&query)).await?;
    Ok(Json(NoteList { notes }))
}

#[derive(Serialize)]
struct Stats {
    notes: i64,
    tags: BTreeMap<String, i64>,
}

async fn stats(State(store): State<AppState>) -> ApiResult<Json<Stats>> {
    let (notes, tags) = with_store(store, |s| Ok((s.count()?, s.tag_counts()?))).await?;
    Ok(Json(Stats { notes, tags }))
}

#[derive(Serialize)]
struct TagCount {
    tag: String,
    count: i64,
}

#[derive(Serialize)]
struct TagList {
    tags: Vec<TagCount>,
}

async fn tags(State(store): State<AppState>) -> ApiResult<Json<TagList>> {
    let counts = with_store(store, |s| s.tag_counts()).await?;
    let mut tags: Vec<TagCount> = counts
        .into_iter()
        .map(|(tag, count)| TagCount { tag, count })
        .collect();
    // Counts arrive ordered by tag; a stable sort keeps that as the tie-breaker.
    tags.sort_by_key(|t| std::cmp::Reverse(t.count));
    Ok(Json(TagList { tags }))
}

#[cfg(test)]
mod tests {
    use super::*;
    use axum::body::Body;
    use axum::http::Request;
    use http_body_util::BodyExt;
    use serde_json::Value;
    use tower::ServiceExt;

    async fn call(app: &Router, method: &str, uri: &str, body: &str) -> (StatusCode, Value) {
        let req = Request::builder()
            .method(method)
            .uri(uri)
            .body(Body::from(body.to_owned()))
            .unwrap();
        let res = app.clone().oneshot(req).await.unwrap();
        let status = res.status();
        let bytes = res.into_body().collect().await.unwrap().to_bytes();
        let value = serde_json::from_slice(&bytes).unwrap_or(Value::Null);
        (status, value)
    }

    fn app() -> Router {
        router(Arc::new(Store::open_in_memory().unwrap()))
    }

    #[tokio::test]
    async fn status_codes() {
        let app = app();
        let (s, v) = call(&app, "POST", "/notes", r#"{"title":"a","tags":["b","a"]}"#).await;
        assert_eq!(s, StatusCode::CREATED);
        assert_eq!(v, json!({"id": 1, "title": "a", "body": "", "tags": ["a", "b"]}));

        assert_eq!(call(&app, "POST", "/notes", "nope").await.0, StatusCode::BAD_REQUEST);
        assert_eq!(call(&app, "DELETE", "/notes", "").await.0, StatusCode::METHOD_NOT_ALLOWED);
        assert_eq!(call(&app, "POST", "/notes/1", "").await.0, StatusCode::METHOD_NOT_ALLOWED);
        assert_eq!(call(&app, "GET", "/nope", "").await.0, StatusCode::NOT_FOUND);
        assert_eq!(call(&app, "GET", "/notes/-1", "").await.0, StatusCode::NOT_FOUND);
        assert_eq!(call(&app, "PUT", "/notes/x", "{}").await.0, StatusCode::NOT_FOUND);
        assert_eq!(call(&app, "GET", "/notes?limit=101", "").await.0, StatusCode::BAD_REQUEST);
        assert_eq!(call(&app, "DELETE", "/notes/1", "").await.0, StatusCode::NO_CONTENT);
        assert_eq!(call(&app, "DELETE", "/notes/1", "").await.0, StatusCode::NOT_FOUND);
    }

    #[tokio::test]
    async fn tags_ordering() {
        let app = app();
        for tags in [r#"["b"]"#, r#"["b","c"]"#, r#"["a"]"#] {
            let body = format!(r#"{{"title":"t","tags":{tags}}}"#);
            call(&app, "POST", "/notes", &body).await;
        }
        let (_, v) = call(&app, "GET", "/tags", "").await;
        assert_eq!(
            v,
            json!({"tags": [
                {"tag": "b", "count": 2}, {"tag": "a", "count": 1}, {"tag": "c", "count": 1}
            ]})
        );
        let (_, v) = call(&app, "GET", "/stats", "").await;
        assert_eq!(v, json!({"notes": 3, "tags": {"a": 1, "b": 2, "c": 1}}));
    }
}

//! notes: a small HTTP notes store backed by SQLite.
//!
//! Usage: `NOTES_DB=<path> notes <port>`

mod api;
mod model;
mod store;

use std::net::{Ipv4Addr, SocketAddr};
use std::process::ExitCode;
use std::sync::Arc;

use store::Store;

#[tokio::main]
async fn main() -> ExitCode {
    match run().await {
        Ok(()) => ExitCode::SUCCESS,
        Err(e) => {
            eprintln!("error: {e}");
            ExitCode::FAILURE
        }
    }
}

async fn run() -> Result<(), Box<dyn std::error::Error>> {
    let port: u16 = std::env::args()
        .nth(1)
        .ok_or("usage: notes <port>")?
        .parse()
        .map_err(|e| format!("invalid port: {e}"))?;
    let db_path = std::env::var_os("NOTES_DB").ok_or("NOTES_DB is not set")?;

    let store = Store::open(&db_path)
        .map_err(|e| format!("cannot open database {}: {e}", db_path.display()))?;
    let app = api::router(Arc::new(store));

    let listener =
        tokio::net::TcpListener::bind(SocketAddr::from((Ipv4Addr::LOCALHOST, port))).await?;
    axum::serve(listener, app)
        .with_graceful_shutdown(async {
            let _ = tokio::signal::ctrl_c().await;
        })
        .await?;
    Ok(())
}

//! Note data types and validation of client input.

use serde::Serialize;
use serde_json::Value;

pub const TITLE_MAX_CHARS: usize = 200;
pub const TAG_MAX_CHARS: usize = 32;

/// A stored note as returned to clients.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct Note {
    pub id: i64,
    pub title: String,
    pub body: String,
    pub tags: Vec<String>,
}

/// Validated contents of a note, as supplied by a create or replace request.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct NoteInput {
    pub title: String,
    pub body: String,
    /// Deduplicated and sorted ascending.
    pub tags: Vec<String>,
}

impl NoteInput {
    /// Parses and validates a raw request body.
    pub fn from_json(bytes: &[u8]) -> Result<Self, String> {
        let value: Value =
            serde_json::from_slice(bytes).map_err(|e| format!("invalid JSON: {e}"))?;
        let Value::Object(mut obj) = value else {
            return Err("request body must be a JSON object".into());
        };

        let title = match obj.remove("title") {
            Some(Value::String(s)) => s.trim().to_owned(),
            Some(_) => return Err("title must be a string".into()),
            None => return Err("title is required".into()),
        };
        let title_len = title.chars().count();
        if title_len == 0 || title_len > TITLE_MAX_CHARS {
            return Err(format!(
                "title must be 1-{TITLE_MAX_CHARS} characters after trimming"
            ));
        }

        let body = match obj.remove("body") {
            None => String::new(),
            Some(Value::String(s)) => s,
            Some(_) => return Err("body must be a string".into()),
        };

        let mut tags = match obj.remove("tags") {
            None => Vec::new(),
            Some(Value::Array(items)) => items
                .into_iter()
                .map(|item| match item {
                    Value::String(tag) if is_valid_tag(&tag) => Ok(tag),
                    _ => Err(format!(
                        "each tag must be 1-{TAG_MAX_CHARS} characters from a-z, 0-9 and -"
                    )),
                })
                .collect::<Result<Vec<_>, _>>()?,
            Some(_) => return Err("tags must be an array of strings".into()),
        };
        tags.sort_unstable();
        tags.dedup();

        Ok(Self { title, body, tags })
    }
}

pub fn is_valid_tag(tag: &str) -> bool {
    (1..=TAG_MAX_CHARS).contains(&tag.len())
        && tag
            .bytes()
            .all(|b| b.is_ascii_lowercase() || b.is_ascii_digit() || b == b'-')
}

/// Filters for listing notes.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ListQuery {
    pub tag: Option<String>,
    pub q: Option<String>,
    pub after: i64,
    pub limit: u32,
}

pub const LIST_LIMIT_MAX: u32 = 100;

impl Default for ListQuery {
    fn default() -> Self {
        Self {
            tag: None,
            q: None,
            after: 0,
            limit: LIST_LIMIT_MAX,
        }
    }
}

impl ListQuery {
    /// Parses a raw (still percent-encoded) query string.
    pub fn parse(raw: Option<&str>) -> Result<Self, String> {
        let mut query = Self::default();
        let Some(raw) = raw else {
            return Ok(query);
        };
        for (key, value) in form_urlencoded::parse(raw.as_bytes()) {
            match key.as_ref() {
                "tag" => query.tag = Some(value.into_owned()),
                "q" => query.q = Some(value.into_owned()),
                "after" => {
                    query.after = parse_integer(&value)
                        .ok_or_else(|| "after must be an integer".to_owned())?;
                }
                "limit" => {
                    query.limit = value
                        .parse::<u32>()
                        .ok()
                        .filter(|n| (1..=LIST_LIMIT_MAX).contains(n))
                        .ok_or_else(|| {
                            format!("limit must be an integer from 1 to {LIST_LIMIT_MAX}")
                        })?;
                }
                _ => {}
            }
        }
        Ok(query)
    }
}

/// Parses a decimal integer, saturating values outside the `i64` range.
fn parse_integer(s: &str) -> Option<i64> {
    let (negative, digits) = match s.as_bytes().first()? {
        b'-' => (true, &s[1..]),
        b'+' => (false, &s[1..]),
        _ => (false, s),
    };
    if digits.is_empty() || !digits.bytes().all(|b| b.is_ascii_digit()) {
        return None;
    }
    Some(s.parse::<i64>().unwrap_or(if negative { i64::MIN } else { i64::MAX }))
}

/// Parses a note id path segment; only positive decimal integers are ids.
pub fn parse_id(segment: &str) -> Option<i64> {
    if segment.is_empty() || !segment.bytes().all(|b| b.is_ascii_digit()) {
        return None;
    }
    segment.parse::<i64>().ok().filter(|&id| id > 0)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn input_defaults_and_normalization() {
        let input =
            NoteInput::from_json(br#"{"title":"  hi  ","tags":["b","a","b"]}"#).unwrap();
        assert_eq!(input.title, "hi");
        assert_eq!(input.body, "");
        assert_eq!(input.tags, ["a", "b"]);
    }

    #[test]
    fn input_rejections() {
        for body in [
            r#"{"title": "#,
            "[]",
            "{}",
            r#"{"title":"   "}"#,
            r#"{"title":5}"#,
            r#"{"title":"x","body":3}"#,
            r#"{"title":"x","body":null}"#,
            r#"{"title":"x","tags":"a"}"#,
            r#"{"title":"x","tags":["Bad"]}"#,
            r#"{"title":"x","tags":[""]}"#,
            r#"{"title":"x","tags":[1]}"#,
        ] {
            assert!(NoteInput::from_json(body.as_bytes()).is_err(), "{body}");
        }
        let long = format!(r#"{{"title":"{}"}}"#, "é".repeat(201));
        assert!(NoteInput::from_json(long.as_bytes()).is_err());
        let max = format!(r#"{{"title":"{}"}}"#, "é".repeat(200));
        assert!(NoteInput::from_json(max.as_bytes()).is_ok());
    }

    #[test]
    fn tag_rules() {
        assert!(is_valid_tag("a-1"));
        assert!(is_valid_tag(&"a".repeat(32)));
        assert!(!is_valid_tag(&"a".repeat(33)));
        assert!(!is_valid_tag("a_b"));
        assert!(!is_valid_tag(""));
    }

    #[test]
    fn list_query() {
        assert_eq!(ListQuery::parse(None).unwrap(), ListQuery::default());
        let q = ListQuery::parse(Some("tag=x&q=hello+world&after=3&limit=5")).unwrap();
        assert_eq!(q.tag.as_deref(), Some("x"));
        assert_eq!(q.q.as_deref(), Some("hello world"));
        assert_eq!((q.after, q.limit), (3, 5));
        for bad in ["limit=0", "limit=101", "limit=x", "limit=", "after=x", "after=", "after=1.5"] {
            assert!(ListQuery::parse(Some(bad)).is_err(), "{bad}");
        }
        assert_eq!(
            ListQuery::parse(Some("after=99999999999999999999")).unwrap().after,
            i64::MAX
        );
        assert_eq!(ListQuery::parse(Some("after=-4")).unwrap().after, -4);
    }

    #[test]
    fn ids() {
        assert_eq!(parse_id("12"), Some(12));
        for bad in ["0", "-1", "+1", "abc", "", "1.0", "99999999999999999999"] {
            assert_eq!(parse_id(bad), None, "{bad}");
        }
    }
}

//! SQLite persistence for notes.

use std::collections::BTreeMap;
use std::path::Path;
use std::sync::{Mutex, MutexGuard};

use rusqlite::{Connection, OptionalExtension, Transaction, params};

use crate::model::{ListQuery, Note, NoteInput};

const SCHEMA: &str = "
    CREATE TABLE IF NOT EXISTS notes (
        id    INTEGER PRIMARY KEY AUTOINCREMENT,
        title TEXT NOT NULL,
        body  TEXT NOT NULL
    );
    CREATE TABLE IF NOT EXISTS note_tags (
        note_id INTEGER NOT NULL REFERENCES notes(id) ON DELETE CASCADE,
        tag     TEXT NOT NULL,
        PRIMARY KEY (note_id, tag)
    ) WITHOUT ROWID;
    CREATE INDEX IF NOT EXISTS note_tags_by_tag ON note_tags (tag, note_id);
";

/// Selects a note's columns plus its tags joined by commas (tags never contain commas).
const NOTE_COLUMNS: &str = "
    n.id, n.title, n.body,
    (SELECT group_concat(t.tag, ',' ORDER BY t.tag) FROM note_tags t WHERE t.note_id = n.id)
";

/// Thread-safe handle to the notes database.
///
/// A single connection serialises access; SQLite allows only one writer at a time anyway,
/// and this avoids `SQLITE_BUSY` handling entirely.
pub struct Store {
    conn: Mutex<Connection>,
}

impl Store {
    pub fn open(path: impl AsRef<Path>) -> rusqlite::Result<Self> {
        Self::init(Connection::open(path)?)
    }

    #[cfg(test)]
    pub fn open_in_memory() -> rusqlite::Result<Self> {
        Self::init(Connection::open_in_memory()?)
    }

    fn init(conn: Connection) -> rusqlite::Result<Self> {
        conn.pragma_update(None, "foreign_keys", true)?;
        // Create the schema before switching journal modes so the main file is written
        // (with its SQLite header) immediately.
        conn.execute_batch(SCHEMA)?;
        conn.pragma_update_and_check(None, "journal_mode", "wal", |_| Ok(()))?;
        conn.pragma_update(None, "synchronous", "normal")?;
        Ok(Self {
            conn: Mutex::new(conn),
        })
    }

    fn conn(&self) -> MutexGuard<'_, Connection> {
        // A panic while holding the lock cannot leave the connection in a bad state
        // (an open transaction is rolled back on drop), so recover from poisoning.
        self.conn.lock().unwrap_or_else(|e| e.into_inner())
    }

    pub fn create(&self, input: &NoteInput) -> rusqlite::Result<Note> {
        let mut conn = self.conn();
        let tx = conn.transaction()?;
        tx.execute(
            "INSERT INTO notes (title, body) VALUES (?1, ?2)",
            params![input.title, input.body],
        )?;
        let id = tx.last_insert_rowid();
        insert_tags(&tx, id, &input.tags)?;
        tx.commit()?;
        Ok(note_from_input(id, input))
    }

    pub fn get(&self, id: i64) -> rusqlite::Result<Option<Note>> {
        let conn = self.conn();
        let mut stmt =
            conn.prepare_cached(&format!("SELECT {NOTE_COLUMNS} FROM notes n WHERE n.id = ?1"))?;
        stmt.query_row([id], row_to_note).optional()
    }

    /// Replaces a note's contents; returns `None` if the note does not exist.
    pub fn replace(&self, id: i64, input: &NoteInput) -> rusqlite::Result<Option<Note>> {
        let mut conn = self.conn();
        let tx = conn.transaction()?;
        let updated = tx.execute(
            "UPDATE notes SET title = ?1, body = ?2 WHERE id = ?3",
            params![input.title, input.body, id],
        )?;
        if updated == 0 {
            return Ok(None);
        }
        tx.execute("DELETE FROM note_tags WHERE note_id = ?1", [id])?;
        insert_tags(&tx, id, &input.tags)?;
        tx.commit()?;
        Ok(Some(note_from_input(id, input)))
    }

    /// Deletes a note; returns whether it existed.
    pub fn delete(&self, id: i64) -> rusqlite::Result<bool> {
        let conn = self.conn();
        Ok(conn.execute("DELETE FROM notes WHERE id = ?1", [id])? > 0)
    }

    pub fn list(&self, query: &ListQuery) -> rusqlite::Result<Vec<Note>> {
        let conn = self.conn();
        let mut stmt = conn.prepare_cached(&format!(
            "SELECT {NOTE_COLUMNS} FROM notes n
             WHERE n.id > ?1
               AND (?2 IS NULL OR EXISTS (
                     SELECT 1 FROM note_tags t WHERE t.note_id = n.id AND t.tag = ?2))
               AND (?3 IS NULL
                    OR instr(lower(n.title), lower(?3)) > 0
                    OR instr(lower(n.body), lower(?3)) > 0)
             ORDER BY n.id
             LIMIT ?4"
        ))?;
        let rows = stmt.query_map(
            params![query.after, query.tag, query.q, query.limit],
            row_to_note,
        )?;
        rows.collect()
    }

    pub fn count(&self) -> rusqlite::Result<i64> {
        self.conn()
            .query_row("SELECT count(*) FROM notes", [], |row| row.get(0))
    }

    /// Number of notes per tag, ordered by tag.
    pub fn tag_counts(&self) -> rusqlite::Result<BTreeMap<String, i64>> {
        let conn = self.conn();
        let mut stmt =
            conn.prepare_cached("SELECT tag, count(*) FROM note_tags GROUP BY tag")?;
        let rows = stmt.query_map([], |row| Ok((row.get(0)?, row.get(1)?)))?;
        rows.collect()
    }
}

fn insert_tags(tx: &Transaction<'_>, id: i64, tags: &[String]) -> rusqlite::Result<()> {
    let mut stmt = tx.prepare_cached("INSERT INTO note_tags (note_id, tag) VALUES (?1, ?2)")?;
    for tag in tags {
        stmt.execute(params![id, tag])?;
    }
    Ok(())
}

fn note_from_input(id: i64, input: &NoteInput) -> Note {
    Note {
        id,
        title: input.title.clone(),
        body: input.body.clone(),
        tags: input.tags.clone(),
    }
}

fn row_to_note(row: &rusqlite::Row<'_>) -> rusqlite::Result<Note> {
    let tags: Option<String> = row.get(3)?;
    Ok(Note {
        id: row.get(0)?,
        title: row.get(1)?,
        body: row.get(2)?,
        tags: tags
            .map(|t| t.split(',').map(str::to_owned).collect())
            .unwrap_or_default(),
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    fn input(title: &str, body: &str, tags: &[&str]) -> NoteInput {
        NoteInput {
            title: title.into(),
            body: body.into(),
            tags: tags.iter().map(|t| t.to_string()).collect(),
        }
    }

    #[test]
    fn crud_and_id_never_reused() {
        let store = Store::open_in_memory().unwrap();
        let a = store.create(&input("a", "", &["x", "y"])).unwrap();
        let b = store.create(&input("b", "", &[])).unwrap();
        assert_eq!((a.id, b.id), (1, 2));
        assert_eq!(store.get(1).unwrap(), Some(a));
        assert!(store.delete(2).unwrap());
        assert!(!store.delete(2).unwrap());
        assert_eq!(store.create(&input("c", "", &[])).unwrap().id, 3);

        let replaced = store.replace(1, &input("A", "body", &["z"])).unwrap().unwrap();
        assert_eq!(store.get(1).unwrap(), Some(replaced));
        assert_eq!(store.replace(2, &input("x", "", &[])).unwrap(), None);
    }

    #[test]
    fn listing_and_stats() {
        let store = Store::open_in_memory().unwrap();
        store.create(&input("Hello", "", &["g"])).unwrap();
        store.create(&input("other", "say HELLO 100%", &["g", "m"])).unwrap();
        store.create(&input("none", "", &[])).unwrap();

        let ids = |q: ListQuery| -> Vec<i64> {
            store.list(&q).unwrap().into_iter().map(|n| n.id).collect()
        };
        assert_eq!(ids(ListQuery::default()), [1, 2, 3]);
        let q = |s: &str| ListQuery::parse(Some(s)).unwrap();
        assert_eq!(ids(q("q=hello")), [1, 2]);
        assert_eq!(ids(q("q=0%25")), [2]);
        assert_eq!(ids(q("q=_")), Vec::<i64>::new());
        assert_eq!(ids(q("tag=m&q=hello")), [2]);
        assert_eq!(ids(q("after=1&limit=1")), [2]);

        store.delete(2).unwrap();
        assert_eq!(store.count().unwrap(), 2);
        assert_eq!(
            store.tag_counts().unwrap(),
            BTreeMap::from([("g".to_owned(), 1)])
        );
    }
